// rps: total request rate; offeredRetries: retries clients want to send this second
function retryBudget(rps, offeredRetries, budgetFraction = 0.10) {
  const allowedCap = Math.floor(rps * budgetFraction);
  const allowed = Math.min(offeredRetries, allowedCap);
  const shed503 = offeredRetries - allowed;
  return { allowedCap, allowed, shed503 };
}

// 10000 RPS, clients offer 2500 retries during a partial outage
console.log(JSON.stringify(retryBudget(10000, 2500)));
